// Deterministic derivation: stretch a seed into a key with iterated hashing
const c=require('node:crypto');
let k=c.createHash('sha256').update("sig alpha bravo delta").digest();
for(let i=0;i<5;i++)k=c.createHash('sha256').update(Buffer.concat([k,Buffer.from([i])])).digest();
console.log('derived key:',k.toString('hex').slice(0,32)+'…');

